package com.campusnova.config;
import org.springframework.boot.context.properties.ConfigurationProperties;
@ConfigurationProperties(prefix="campusnova.college") public class CollegeProfile { private String officialName; private String shortName; private String location; private String officialDomain; private String address; private String affiliation; private String institutionType; public String getOfficialName(){return officialName;} public void setOfficialName(String v){officialName=v;} public String getShortName(){return shortName;} public void setShortName(String v){shortName=v;} public String getLocation(){return location;} public void setLocation(String v){location=v;} public String getOfficialDomain(){return officialDomain;} public void setOfficialDomain(String v){officialDomain=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public String getAffiliation(){return affiliation;} public void setAffiliation(String v){affiliation=v;} public String getInstitutionType(){return institutionType;} public void setInstitutionType(String v){institutionType=v;} }
